To simplify this trigonometric expression, we can start by finding a common denominator.
\end{ thinking }  <-end thinking >=><note>

\begin{equation}
\begin{split}
\frac{\sin x}{\cos x} + \frac{\cos x}{1 + \sin x} = \frac{\sin x(1 + \sin x) + \cos^2 x}{\cos x(1 + \sin x)} = \frac{\sin x + \sin^2 x + \cos^2 x}{\cos x(1 + \sin x)}
\end{split}
\end{equation}

\begin{equation}
\text{Now, using the Pythagorean identity, } \sin^2 x + \cos^2 x = 1.
\end{equation}

\begin{equation}
\begin{split}
\frac{\sin x + 1}{\cos x(1 + \sin x)} = \frac{1}{\cos x}.
\end{split}
\end{equation}

\begin{equation}
\boxed{ \frac{1}{\cos x} }
\end{equation}

